    circuit.tick().mz(&[0, 1]);

    let svg = circuit.to_svg();
    let tikz = circuit.to_tikz();
    let style = DiagramStyle::builder()
        .color(false)
        .show_measurement_ids(true)
        .build();
    let monochrome_svg = circuit.render_with(&style).svg();

